from decimal import Decimal
import glob

def amount(raw, v):
    raw = raw.strip()
    return Decimal(raw.replace(".", "").replace(",", ".")) if v == "v1" else Decimal(raw)

for region, delim in (("eu", ";"), ("apac", "|")):
    for path in sorted(glob.glob(f"feeds/{region}/2026-*.csv")):
        lines = open(path).read().splitlines()
        v = next(l.split(":",1)[1].strip() for l in lines if l.startswith("# format:"))
        rows = [l for l in lines if l and not l.startswith("#")][1:]
        totals = {}
        for row in rows:
            d, a, x = row.split(delim)
            totals[d[:7]] = totals.get(d[:7], 0) + amount(x, v)
        print(path, v, {k: str(val) for k, val in totals.items()})
PY

